"""
AttendanceChimp - Django Models
================================

This module defines the database models for the AttendanceChimp attendance
tracking application.

The application uses separate profile tables for instructors and students
rather than a single Users table. Each profile is associated with Django's
built-in User model, which handles authentication and login credentials.

Database Structure
------------------

1. InstructorProfile
   Stores instructor-specific information and is associated with a Django User.

2. StudentProfile
   Stores student-specific information and is associated with a Django User.

3. Course
   Represents a course taught by an instructor. Each course includes a name,
   meeting schedule, and other identifying information.

4. Enrollment
   Represents the relationship between a student and a course. A student may
   enroll in multiple courses, and a course may contain multiple students.

5. Lecture
   Represents an individual class session belonging to a course. Each lecture
   has a date and a unique QR identifier used for attendance tracking.

6. QRCodeUpload
   Stores QR code attendance submissions made by students. Each submission
   belongs to a student and may optionally reference a specific lecture.

Relationships
-------------

InstructorProfile -> Course:
    One instructor can teach multiple courses.

StudentProfile -> Enrollment:
    One student can have multiple enrollments.

Course -> Enrollment:
    One course can have multiple enrollments.

Course -> Lecture:
    One course can have multiple lectures.

StudentProfile -> QRCodeUpload:
    One student can submit multiple QR code uploads.

Lecture -> QRCodeUpload:
    One lecture can have multiple QR code uploads.

Design Notes
------------

- Django's built-in User model handles authentication.
- Separate profile models distinguish instructors from students.
- ForeignKey relationships use descriptive related_name values.
- Unique constraints prevent duplicate student enrollments in a course.
- Unique QR identifiers allow lectures to be identified independently.
- QRCodeUpload.lecture is nullable to allow uploads that have not yet
  been associated with a lecture.
"""

import uuid

from django.conf import settings
from django.core.exceptions import ValidationError
from django.db import models
from django.utils import timezone


class InstructorProfile(models.Model):
    """
    Represents an instructor in the AttendanceChimp application.

    This model stores instructor-specific information separately from student
    information. Each instructor profile is associated with one Django User
    account, which provides authentication and login functionality.

    Attributes:
        user:
            One-to-one relationship with Django's built-in User model.
            Each user can have only one instructor profile.

        employee_id:
            Optional institutional employee identifier.

        department:
            Optional academic department associated with the instructor.

        created_at:
            Timestamp indicating when the instructor profile was created.

    Relationships:
        An instructor may teach multiple courses through the Course model.

    Example:
        instructor = InstructorProfile.objects.create(
            user=user,
            employee_id="INS001",
            department="Computer Science"
        )
    """

    user = models.OneToOneField(
        settings.AUTH_USER_MODEL,
        on_delete=models.CASCADE,
        related_name="instructor_profile",
    )

    employee_id = models.CharField(
        max_length=50,
        unique=True,
        null=True,
        blank=True,
    )

    department = models.CharField(
        max_length=100,
        blank=True,
    )

    created_at = models.DateTimeField(
        auto_now_add=True,
    )

    def __str__(self):
        """Return the instructor's username."""
        return self.user.get_username()


class StudentProfile(models.Model):
    """
    Represents a student in the AttendanceChimp application.

    Each student profile is associated with one Django User account.
    Student-specific information is stored independently from instructor
    information.

    Attributes:
        user:
            One-to-one relationship with Django's built-in User model.

        student_id:
            Unique institutional student identifier.

        major:
            Optional academic major.

        created_at:
            Timestamp indicating when the student profile was created.

    Relationships:
        A student may enroll in multiple courses through the Enrollment model.
        A student may also submit multiple QRCodeUpload records.

    Example:
        student = StudentProfile.objects.create(
            user=user,
            student_id="STU001",
            major="Data Science"
        )
    """

    user = models.OneToOneField(
        settings.AUTH_USER_MODEL,
        on_delete=models.CASCADE,
        related_name="student_profile",
    )

    student_id = models.CharField(
        max_length=50,
        unique=True,
    )

    major = models.CharField(
        max_length=100,
        blank=True,
    )

    created_at = models.DateTimeField(
        auto_now_add=True,
    )

    def __str__(self):
        """Return the student's username."""
        return self.user.get_username()


class Course(models.Model):
    """
    Represents a course offered in AttendanceChimp.

    Each course is assigned to one instructor and can contain multiple
    enrolled students and lecture sessions.

    Attributes:
        name:
            Name of the course.

        course_code:
            Unique identifier for the course, such as DATA11900.

        instructor:
            ForeignKey relationship to InstructorProfile.

        meeting_schedule:
            Human-readable description of the course meeting schedule.
            For example, "Monday and Wednesday, 10:00 AM - 11:15 AM".

        created_at:
            Timestamp indicating when the course was created.

    Relationships:
        One instructor may teach multiple courses.
        One course may have multiple enrollments and lectures.

    Helper Methods:
        get_enrolled_students():
            Returns all students enrolled in this course.

        get_lectures():
            Returns all lectures associated with this course.
    """

    name = models.CharField(
        max_length=200,
    )

    course_code = models.CharField(
        max_length=50,
        unique=True,
    )

    instructor = models.ForeignKey(
        InstructorProfile,
        on_delete=models.CASCADE,
        related_name="courses",
    )

    meeting_schedule = models.CharField(
        max_length=255,
        help_text=(
            "Course meeting schedule, e.g. "
            "'Monday and Wednesday, 10:00 AM - 11:15 AM'."
        ),
    )

    created_at = models.DateTimeField(
        auto_now_add=True,
    )

    def get_enrolled_students(self):
        """
        Return all students enrolled in this course.

        Returns:
            QuerySet: StudentProfile objects associated with this course.
        """
        return StudentProfile.objects.filter(
            enrollments__course=self
        )

    def get_lectures(self):
        """
        Return all lecture sessions associated with this course.

        Returns:
            QuerySet: Lecture objects belonging to this course.
        """
        return self.lectures.all()

    def __str__(self):
        """Return the course name and course code."""
        return f"{self.course_code} - {self.name}"


class Enrollment(models.Model):
    """
    Represents a student's enrollment in a course.

    This model implements the many-to-many relationship between students
    and courses.

    A student may enroll in several courses, and each course may contain
    multiple students.

    Attributes:
        student:
            ForeignKey relationship to StudentProfile.

        course:
            ForeignKey relationship to Course.

        enrolled_at:
            Timestamp indicating when the student enrolled.

    Constraints:
        A student cannot have duplicate enrollment records for the same course.

    Helper Methods:
        is_active():
            Returns whether the enrollment is currently active.

    Example:
        Enrollment.objects.create(
            student=student,
            course=course
        )
    """

    student = models.ForeignKey(
        StudentProfile,
        on_delete=models.CASCADE,
        related_name="enrollments",
    )

    course = models.ForeignKey(
        Course,
        on_delete=models.CASCADE,
        related_name="enrollments",
    )

    enrolled_at = models.DateTimeField(
        auto_now_add=True,
    )

    class Meta:
        """Define enrollment constraints and database ordering."""

        constraints = [
            models.UniqueConstraint(
                fields=["student", "course"],
                name="unique_student_course_enrollment",
            )
        ]

        ordering = ["course", "student"]

    def is_active(self):
        """
        Return whether this enrollment is active.

        The current implementation treats every existing enrollment
        as active. A future version could introduce an is_active BooleanField
        or enrollment status field.

        Returns:
            bool: True if the enrollment exists.
        """
        return self.pk is not None

    def __str__(self):
        """Return a readable enrollment description."""
        return (
            f"{self.student} enrolled in "
            f"{self.course}"
        )


class Lecture(models.Model):
    """
    Represents an individual lecture session for a course.

    A course may have multiple lecture sessions. Each lecture has a date
    and a unique QR identifier that can be used to generate a QR code
    for attendance verification.

    Attributes:
        course:
            ForeignKey relationship to Course.

        date:
            Date on which the lecture takes place.

        qr_identifier:
            Unique UUID identifying the lecture's attendance QR code.

        created_at:
            Timestamp indicating when the lecture record was created.

    Relationships:
        Each lecture belongs to exactly one course.
        Each lecture may have multiple QRCodeUpload records.

    Helper Methods:
        generate_qr_identifier():
            Generates a new UUID for the lecture.

        get_attendance_count():
            Returns the number of QR code uploads associated with this lecture.

    Security Note:
        The QR identifier is a unique identifier, not a complete attendance
        security mechanism. A production application should additionally
        validate enrollment, expiration time, and duplicate submissions.
    """

    course = models.ForeignKey(
        Course,
        on_delete=models.CASCADE,
        related_name="lectures",
    )

    date = models.DateField(
        default=timezone.localdate,
    )

    qr_identifier = models.UUIDField(
        default=uuid.uuid4,
        unique=True,
        editable=False,
    )

    created_at = models.DateTimeField(
        auto_now_add=True,
    )

    @staticmethod
    def generate_qr_identifier():
        """
        Generate a unique UUID for a lecture.

        Returns:
            UUID: A newly generated QR identifier.
        """
        return uuid.uuid4()

    def get_attendance_count(self):
        """
        Return the number of QR code uploads associated with this lecture.

        Returns:
            int: Number of QRCodeUpload records for this lecture.
        """
        return self.qr_uploads.count()

    def __str__(self):
        """Return the course name and lecture date."""
        return f"{self.course.name} - {self.date}"


class QRCodeUpload(models.Model):
    """
    Represents a student's QR code attendance submission.

    Each upload is associated with a student and may optionally reference
    a lecture.

    This model records which student submitted a QR code and which lecture
    the submission corresponds to. The lecture relationship is optional
    because an upload may initially be received before its lecture has
    been identified.

    Attributes:
        student:
            ForeignKey relationship to StudentProfile.

        lecture:
            Optional ForeignKey relationship to Lecture.

        uploaded_at:
            Timestamp indicating when the QR code was submitted.

        qr_image:
            Optional uploaded image containing the QR code.

        is_valid:
            Boolean indicating whether the upload has been validated.

    Relationships:
        Each upload belongs to one student.
        Each upload may belong to one lecture.

    Helper Methods:
        validate_enrollment():
            Checks whether the student is enrolled in the lecture's course.

    Notes:
        QR image storage requires Django's FileField support and a configured
        MEDIA_ROOT and MEDIA_URL. The uploaded file should be validated by
        the application before being processed.
    """

    student = models.ForeignKey(
        StudentProfile,
        on_delete=models.CASCADE,
        related_name="qr_uploads",
    )

    lecture = models.ForeignKey(
        Lecture,
        on_delete=models.SET_NULL,
        related_name="qr_uploads",
        null=True,
        blank=True,
    )

    qr_image = models.ImageField(
        upload_to="attendance_qr_uploads/",
        null=True,
        blank=True,
    )

    uploaded_at = models.DateTimeField(
        auto_now_add=True,
    )

    is_valid = models.BooleanField(
        default=False,
    )

    def validate_enrollment(self):
        """
        Check whether the student is enrolled in the lecture's course.

        Returns:
            bool: True if the student is enrolled in the course.
            False if the lecture is missing or the student is not enrolled.

        This method does not validate the QR identifier itself. QR decoding
        and identifier verification should be handled by the attendance
        processing service.
        """
        if self.lecture is None:
            return False

        return Enrollment.objects.filter(
            student=self.student,
            course=self.lecture.course,
        ).exists()

    def clean(self):
        """
        Validate the QR code upload.

        Ensures that the student is enrolled in the course associated with
        the lecture, if a lecture has been assigned.
        """
        super().clean()

        if self.lecture is not None and not self.validate_enrollment():
            raise ValidationError(
                {
                    "lecture": (
                        "The student must be enrolled in the lecture's course."
                    )
                }
            )

    def __str__(self):
        """Return a readable QR code upload description."""
        if self.lecture:
            return (
                f"{self.student} - "
                f"{self.lecture.course.name} - "
                f"{self.uploaded_at}"
            )

        return f"{self.student} - Unassigned QR Upload"
